15: function ToastProvider({ children }) {
16:   const [toasts, setToasts] = useState([]);
17:   const addToast = useCallback((message, type = 'info') => {
18:     const id = Date.now();
19:     setToasts(p => [...p, { id, message, type }]);
20:     setTimeout(() => setToasts(p => p.filter(t => t.id !== id)), 4000);
21:   }, []);
22:   const icons = { success: CheckCircle, error: AlertTriangle, info: Info };
23:   const colors = { success: 'border-emerald-400 bg-emerald-50 text-emerald-800', error: 'border-red-400 bg-red-50 text-red-800', info: 'border-teal-400 bg-teal-50 text-teal-800' };
24:   return (
25:     <ToastContext.Provider value={{ addToast }}>
26:       {children}
27:       <div className="fixed bottom-4 right-4 z-50 space-y-2 max-w-xs w-full">
28:         {toasts.map(t => {
29:           const Icon = icons[t.type] || Info;
30:           return (
31:             <div key={t.id} className={`flex items-start gap-2 border-l-4 rounded-lg px-3 py-2.5 shadow-md text-xs font-medium ${colors[t.type] || colors.info}`}>
32:               <Icon className="w-4 h-4 flex-shrink-0 mt-0.5" />
33:               <span className="flex-1">{t.message}</span>
34:               <button onClick={() => setToasts(p => p.filter(x => x.id !== t.id))}><X className="w-3.5 h-3.5" /></button>
35:             </div>
36:           );
37:         })}
38:       </div>
39:     </ToastContext.Provider>
40:   );
