  EyeOff,
  BadgeCheck,
  Info,
} from 'lucide-react';
import { useAuth } from '../auth/authContext';
// api helpers — operate directly on localStorage sc_users store
const api = {
  _load: () => { try { return JSON.parse(localStorage.getItem('sc_users') || '[]'); } catch { return []; } },
  _save: (users) => localStorage.setItem('sc_users', JSON.stringify(users)),
  createUser: async (payload) => {
    await new Promise(r => setTimeout(r, 300));
    const users = api._load();
    if (users.find(u => u.email === payload.email)) return { success: false, error: 'A user with this email already exists.' };
    const user = { ...payload, id: `u_${Date.now()}`, status: 'active', createdAt: new Date().toISOString(), lastLogin: null };
    delete user.password;
    api._save([...users, user]);
    return { success: true, user };
  },
  updateUser: async (id, payload) => {
    await new Promise(r => setTimeout(r, 300));
    const users = api._load();
    const idx = users.findIndex(u => u.id === id);
    if (idx === -1) return { success: false, error: 'User not found.' };
    const updated = { ...users[idx], ...payload };
    delete updated.password;
    users[idx] = updated;
    api._save(users);
    return { success: true, user: updated };
  },
  deactivateUser: async (id) => {
    await new Promise(r => setTimeout(r, 200));
    const users = api._load();
    const idx = users.findIndex(u => u.id === id);
    if (idx === -1) return { success: false, error: 'User not found.' };
    users[idx] = { ...users[idx], status: 'inactive' };
    api._save(users);
    return { success: true };
  },
  activateUser: async (id) => {
    await new Promise(r => setTimeout(r, 200));
    const users = api._load();
    const idx = users.findIndex(u => u.id === id);
    if (idx === -1) return { success: false, error: 'User not found.' };
    users[idx] = { ...users[idx], status: 'active' };
    api._save(users);
    return { success: true };
  },
};
import { PERMISSIONS, ROLE_PERMISSIONS, PERMISSION_METADATA } from '../auth/permissions';

