304: export async function submitUWDecision(caseId, decision) {
305:   ensureSeeded();
306:   await delay(300);
307:   const cases = lsGet('uw_cases', SEED_CASES);
308:   const statusMap = {
309:     'Approve': 'Bound',
310:     'Approve with Conditions': 'Decision Made',
311:     'Decline': 'Decision Made',
312:     'Request More Info': 'Pending IR',
313:   };
314:   const newStatus = statusMap[decision.type] || 'Decision Made';
315:   const updated = cases.map(c => c.id === caseId ? { ...c, status: newStatus, lastDecision: decision } : c);
316:   lsSet('uw_cases', updated);
317: 
318:   // Log to audit
319:   const auditEntry = {
320:     id: `AUD-${Date.now()}`,
321:     caseId,
322:     action: `UW Decision: ${decision.type}`,
323:     actor: decision.uwName || 'Underwriter',
324:     detail: decision.notes || '',
325:     timestamp: new Date().toISOString(),
326:   };
327:   const log = lsGet('uw_audit_log', []);
328:   lsSet('uw_audit_log', [auditEntry, ...log]);
329: 
330:   return { success: true, newStatus, auditEntry };
331: }
