200: // ─── Portfolio Metrics ────────────────────────────────────────────────────────
201: export async function getPortfolioMetrics() {
202:   ensureSeeded();
203:   await delay();
204:   const cases = lsGet('uw_cases', SEED_CASES);
205:   const alerts = lsGet('uw_alerts', SEED_ALERTS);
206:   const irs = lsGet('uw_info_requests', SEED_INFO_REQUESTS);
207: 
208:   const active = cases.filter(c => c.status !== 'Bound');
209:   const expiring30 = cases.filter(c => c.daysToExpiry <= 30);
210:   const expiring60 = cases.filter(c => c.daysToExpiry > 30 && c.daysToExpiry <= 60);
211:   const expiring90 = cases.filter(c => c.daysToExpiry > 60 && c.daysToExpiry <= 90);
212:   const totalExposure = cases.reduce((s, c) => s + c.bondPenalty, 0);
213:   const activeAlerts = alerts.filter(a => !a.acknowledged);
214:   const pendingIRs = irs.filter(i => i.status !== 'Received');
215: 
216:   return {
217:     totalActiveCases: active.length,
218:     pendingDecision: cases.filter(c => c.status === 'AI Brief Ready' || c.status === 'In Review').length,
219:     expiringIn30Days: expiring30.length,
220:     expiringIn60Days: expiring60.length,
221:     expiringIn90Days: expiring90.length,
222:     aggregateExposure: totalExposure,
223:     renewalHitRate: 84,
224:     activeRiskAlerts: activeAlerts.length,
225:     pendingInfoRequests: pendingIRs.length,
226:     aiAdoptionRate: 78,
227:     overrideRate: 12,
228:   };
229: }
