693: /**
694:  * confirmImport — Persists validated rows from a preview result.
695:  * Skips error rows and duplicates. Appends audit log entry.
696:  * Returns { imported, skipped, errors }
697:  */
698: export async function confirmImport(batchId, previewResult) {
699:   ensureImportSeeded();
700:   await delay(500);
701: 
702:   const { rows = [], errors = [], duplicates = [], summary = {}, filename = 'upload.xlsx', sourceType = 'Excel' } = previewResult;
703: 
704:   const records = lsGet('uw_renewal_records', SEED_RENEWAL_RECORDS);
705:   const batches = lsGet('uw_import_batches', SEED_IMPORT_BATCHES);
706:   const importErrors = lsGet('uw_import_errors', SEED_IMPORT_ERRORS);
707: 
708:   const now = new Date().toISOString();
709:   let imported = 0;
710:   let skipped = 0;
711: 
712:   rows.forEach(r => {
713:     if (r._status === 'valid') {
714:       const newRecord = {
715:         id: `RR-${batchId}-${r.row}`,
716:         caseId: null,
717:         principalName: r.principalName,
718:         principalId: r.principalId,
719:         bondType: r.bondType,
720:         canonicalKey: r.canonicalKey,
721:         lastUpdated: now,
722:         dataGroups: {
723:           activeBonds: { bondNumber: `SB-NEW-${r.principalId}`, obligeeName: r.obligeeName, bondPenalty: Number(r.bondPenalty), effectiveDate: r.effectiveDate, expiryDate: r.expiryDate, bondStatus: 'Active', renewalCount: 1 },
724:           customerSince: { firstBondDate: r.effectiveDate, relationshipYears: 0, accountTier: 'Standard' },
725:           fliqRate: { currentRate: 1.00, marketRate: 1.00, rateVariance: 0.00, rateCategory: 'At Market' },
726:           dtf: { averageDTF: null, lastDTF: null, dtfTrend: 'Unknown', dtfCategory: 'Unknown' },
727:           pms: { pmsScore: null, pmsCategory: 'Pending', lastReviewDate: null, reviewedBy: null },
728:           entryTypes: { primaryEntry: 'Import', secondaryEntry: null, entryChannel: 'File Upload' },
729:           extendedSuspendedEntries: { extendedCount: 0, suspendedCount: 0, lastExtensionDate: null, reason: null },
730:           addCvd: { addFlag: false, cvdFlag: false, addAmount: 0, cvdAmount: 0, notes: null },
731:           ldClaims: { claimCount: 0, totalClaimAmount: 0, lastClaimDate: null, openClaims: 0 },
732:           idBills: { outstandingBills: 0, totalBillAmount: 0, overdueCount: 0 },
733:           otherClaims: { miscClaimCount: 0, miscClaimAmount: 0, notes: null },
734:           premium: { currentPremium: Number(r.premium), priorPremium: null, premiumChange: null, premiumChangePercent: null },
735:           paidClaims: { totalPaidClaims: 0, paidThisYear: 0, lossRatio: 0.0 },
736:           collateral: { collateralHeld: 0, collateralType: null, collateralExpiry: null },
737:           gia: { giaExecuted: false, giaDate: null, giaParties: null, giaVersion: null },
738:           openExposure: { totalExposure: Number(r.bondPenalty), netExposure: Number(r.bondPenalty), reinsuranceRecoverable: 0, exposureCategory: 'Pending' },
739:         },
740:         sourceLineage: Object.fromEntries(
741:           ['activeBonds','customerSince','fliqRate','dtf','pms','entryTypes','extendedSuspendedEntries',
742:            'addCvd','ldClaims','idBills','otherClaims','premium','paidClaims','collateral','gia','openExposure']
743:           .map(g => [g, { sourceFile: filename, sourceSheet: 'Sheet1', sourceRow: r.row, importBatchId: batchId, importTimestamp: now }])
744:         ),
745:       };
746:       records.push(newRecord);
747:       imported++;
748:     } else {
749:       skipped++;
750:     }
751:   });
752: 
753:   lsSet('uw_renewal_records', records);
754: 
755:   // Persist errors
756:   const newErrors = errors.map((e, i) => ({ id: `ERR-${batchId}-${i}`, batchId, ...e }));
757:   lsSet('uw_import_errors', [...importErrors, ...newErrors]);
758: 
759:   // Persist batch record
760:   const batch = {
761:     id: batchId,
762:     filename,
763:     sourceType,
764:     uploadedBy: 'admin@suretyiq.com',
765:     uploadedAt: now,
766:     importedAt: now,
767:     status: errors.length > 0 ? 'Completed with Errors' : 'Completed',
768:     totalRows: summary.totalRows || rows.length,
769:     validRows: imported,
770:     errorRows: summary.errorRows || 0,
771:     duplicateRows: summary.duplicateRows || 0,
772:     sheets: ['Sheet1'],
773:     notes: `Imported via UI. ${imported} records added, ${skipped} skipped.`,
774:   };
775:   lsSet('uw_import_batches', [batch, ...batches]);
776: 
777:   // Audit log
778:   const auditEntry = {
779:     id: `AUD-IMP-${Date.now()}`,
780:     action: `Data Import Confirmed: ${filename}`,
781:     actor: 'admin@suretyiq.com',
782:     detail: `Batch ${batchId}: ${imported} imported, ${skipped} skipped, ${errors.length} errors.`,
783:     timestamp: now,
784:   };
785:   const log = lsGet('uw_audit_log', []);
786:   lsSet('uw_audit_log', [auditEntry, ...log]);
787: 
788:   return { imported, skipped, errors: newErrors, batchId };
789: }
