827:     records = records.filter(r =>
828:       (r.principalName || '').toLowerCase().includes(q) ||
829:       (r.principalId || '').toLowerCase().includes(q) ||
830:       (r.bondType || '').toLowerCase().includes(q) ||
831:       (r.canonicalKey || '').toLowerCase().includes(q)
832:     );
833:   }
834:   return records;
835: }
