322:     action: `UW Decision: ${decision.type}`,
323:     actor: decision.uwName || 'Underwriter',
324:     detail: decision.notes || '',
325:     timestamp: new Date().toISOString(),
326:   };
327:   const log = lsGet('uw_audit_log', []);
328:   lsSet('uw_audit_log', [auditEntry, ...log]);
329: 
330:   return { success: true, newStatus, auditEntry };
331: }
