400: export async function updateUserProfile(userId, updates) {
401:   await delay(200);
402: 
403:   // ── Primary path: update the suretyiq_users store (shared with auth system) ──
404:   if (userId) {
405:     const users = lsGet('suretyiq_users', []);
406:     const idx = users.findIndex(u => u.id === userId);
407:     if (idx !== -1) {
408:       const updated = { ...users[idx], ...updates, updatedAt: new Date().toISOString() };
409:       users[idx] = updated;
410:       lsSet('suretyiq_users', users);
411:       return updated;
412:     }
413:   }
414: 
415:   // ── Fallback: legacy uw_user_profile key (pre-auth era) ──
416:   const current = lsGet('uw_user_profile', {});
417:   const updated = { ...current, ...updates };
418:   lsSet('uw_user_profile', updated);
419:   return updated;
420: }
