// ─── User Profile ─────────────────────────────────────────────────────────────
// NOTE: updateUserProfile delegates to the suretyiq_users store (same key used
// by mockUsers.js and authContext) so that profile edits are immediately visible
// to the auth system without a page reload.

export async function getUserProfile(userId) {
  await delay();
  // If a userId is supplied, look up the canonical user record from the auth store
  if (userId) {
    const users = lsGet('suretyiq_users', []);
    const user = users.find(u => u.id === userId);
    if (user) return user;
  }
  // Fallback: legacy uw_user_profile key (pre-auth era, kept for compatibility)
  return lsGet('uw_user_profile', {
    id: 'U-001',
    name: 'Sarah Chen',
    email: 'sarah.chen@surety.com',
    role: 'Senior Underwriter',
    region: 'Mountain West',
    avatar: null,
    phone: '+1 (303) 555-0192',
    department: 'Commercial Surety',
    notifications: { email: true, inApp: true, sms: false },
  });
}

export async function updateUserProfile(userId, updates) {
  await delay(200);

  // ── Primary path: update the suretyiq_users store (shared with auth system) ──
  if (userId) {
    const users = lsGet('suretyiq_users', []);
    const idx = users.findIndex(u => u.id === userId);
    if (idx !== -1) {
      const updated = { ...users[idx], ...updates, updatedAt: new Date().toISOString() };
      users[idx] = updated;
      lsSet('suretyiq_users', users);
      return updated;
    }
  }

  // ── Fallback: legacy uw_user_profile key (pre-auth era) ──
  const current = lsGet('uw_user_profile', {});
  const updated = { ...current, ...updates };
  lsSet('uw_user_profile', updated);
  return updated;
}

