  const alerts = lsGet('uw_alerts', SEED_ALERTS);
  const updated = alerts.map(a => a.id === id ? { ...a, acknowledged: true } : a);
  lsSet('uw_alerts', updated);
  return updated.find(a => a.id === id);
}

