/**
 * previewImport — Simulates parsing an uploaded file and validating rows.
 * In prototype mode, generates synthetic preview rows from the file name.
 * Returns { batchId, rows, errors, duplicates, summary }
 */
export async function previewImport(fileData, columnMappings = {}) {
  ensureImportSeeded();
  await delay(400);

  const batchId = `IB-${Date.now()}`;
  const existingRecords = lsGet('uw_renewal_records', SEED_RENEWAL_RECORDS);
  const existingKeys = new Set(existingRecords.map(r => r.canonicalKey));

  // Simulate parsed rows from the uploaded file
  const simulatedRows = [
    { row: 1, principalId: 'PRIN-10051', principalName: 'Harborview Contractors Inc.', bondType: 'Performance Bond', obligeeName: 'Port of Seattle', bondPenalty: 3800000, premium: 38000, effectiveDate: '2025-10-01', expiryDate: '2026-10-01', canonicalKey: 'PRIN-10051|Performance Bond|Port of Seattle' },
    { row: 2, principalId: 'PRIN-10052', principalName: 'Delta Dredging Corp.', bondType: 'Payment Bond', obligeeName: 'Army Corps of Engineers', bondPenalty: 7200000, premium: 72000, effectiveDate: '2025-11-15', expiryDate: '2026-11-15', canonicalKey: 'PRIN-10052|Payment Bond|Army Corps of Engineers' },
    { row: 3, principalId: 'PRIN-10043', principalName: 'Summit Electrical Services', bondType: 'Subdivision Bond', obligeeName: 'Clark County NV', bondPenalty: 1850000, premium: 18500, effectiveDate: '2025-08-20', expiryDate: '2026-11-15', canonicalKey: 'PRIN-10043|Subdivision Bond|Clark County NV' },
    { row: 4, principalId: '', principalName: 'Unknown Entity LLC', bondType: 'Performance Bond', obligeeName: 'City of Phoenix', bondPenalty: null, premium: 'N/A', effectiveDate: '2026-01-01', expiryDate: '2027-01-01', canonicalKey: '' },
  ];

  const errors = [];
  const duplicates = [];
  const validRows = [];

  simulatedRows.forEach(r => {
    const rowErrors = [];
    if (!r.principalId) rowErrors.push({ field: 'principalId', errorType: 'Missing Required', message: 'Principal ID is required.' });
    if (!r.bondPenalty || isNaN(Number(r.bondPenalty))) rowErrors.push({ field: 'bondPenalty', errorType: 'Invalid Numeric', message: `Bond Penalty must be a valid number. Received: "${r.bondPenalty}".` });
    if (r.premium === 'N/A' || isNaN(Number(r.premium))) rowErrors.push({ field: 'premium', errorType: 'Invalid Numeric', message: `Premium must be a valid number. Received: "${r.premium}".` });

    const isDuplicate = r.canonicalKey && existingKeys.has(r.canonicalKey);
    if (isDuplicate) duplicates.push({ row: r.row, canonicalKey: r.canonicalKey, message: `Duplicate: record already exists for ${r.principalName}.` });

    if (rowErrors.length > 0) {
      errors.push(...rowErrors.map(e => ({ ...e, row: r.row, batchId })));
    } else if (!isDuplicate) {
      validRows.push({ ...r, _status: 'valid' });
    }
  });

  const preview = simulatedRows.map(r => ({
    ...r,
    _status: errors.some(e => e.row === r.row) ? 'error'
      : duplicates.some(d => d.row === r.row) ? 'duplicate'
      : 'valid',
    _errors: errors.filter(e => e.row === r.row),
  }));

  return {
    batchId,
    filename: fileData?.name || 'upload.xlsx',
    sourceType: (fileData?.name || '').endsWith('.csv') ? 'CSV' : 'Excel',
    rows: preview,
    errors,
    duplicates,
    summary: {
      totalRows: simulatedRows.length,
      validRows: validRows.length,
      errorRows: errors.length > 0 ? [...new Set(errors.map(e => e.row))].length : 0,
      duplicateRows: duplicates.length,
    },
  };
}

/**
 * confirmImport — Persists validated rows from a preview result.
 * Skips error rows and duplicates. Appends audit log entry.
 * Returns { imported, skipped, errors }
 */
export async function confirmImport(batchId, previewResult) {
  ensureImportSeeded();
  await delay(500);

  const { rows = [], errors = [], duplicates = [], summary = {}, filename = 'upload.xlsx', sourceType = 'Excel' } = previewResult;

  const records = lsGet('uw_renewal_records', SEED_RENEWAL_RECORDS);
  const batches = lsGet('uw_import_batches', SEED_IMPORT_BATCHES);
  const importErrors = lsGet('uw_import_errors', SEED_IMPORT_ERRORS);

  const now = new Date().toISOString();
  let imported = 0;
  let skipped = 0;

  rows.forEach(r => {
    if (r._status === 'valid') {
      const newRecord = {
        id: `RR-${batchId}-${r.row}`,
        caseId: null,
        principalName: r.principalName,
        principalId: r.principalId,
        bondType: r.bondType,
        canonicalKey: r.canonicalKey,
        lastUpdated: now,
        dataGroups: {
          activeBonds: { bondNumber: `SB-NEW-${r.principalId}`, obligeeName: r.obligeeName, bondPenalty: Number(r.bondPenalty), effectiveDate: r.effectiveDate, expiryDate: r.expiryDate, bondStatus: 'Active', renewalCount: 1 },
          customerSince: { firstBondDate: r.effectiveDate, relationshipYears: 0, accountTier: 'Standard' },
          fliqRate: { currentRate: 1.00, marketRate: 1.00, rateVariance: 0.00, rateCategory: 'At Market' },
          dtf: { averageDTF: null, lastDTF: null, dtfTrend: 'Unknown', dtfCategory: 'Unknown' },
          pms: { pmsScore: null, pmsCategory: 'Pending', lastReviewDate: null, reviewedBy: null },
          entryTypes: { primaryEntry: 'Import', secondaryEntry: null, entryChannel: 'File Upload' },
          extendedSuspendedEntries: { extendedCount: 0, suspendedCount: 0, lastExtensionDate: null, reason: null },
          addCvd: { addFlag: false, cvdFlag: false, addAmount: 0, cvdAmount: 0, notes: null },
          ldClaims: { claimCount: 0, totalClaimAmount: 0, lastClaimDate: null, openClaims: 0 },
          idBills: { outstandingBills: 0, totalBillAmount: 0, overdueCount: 0 },
          otherClaims: { miscClaimCount: 0, miscClaimAmount: 0, notes: null },
          premium: { currentPremium: Number(r.premium), priorPremium: null, premiumChange: null, premiumChangePercent: null },
          paidClaims: { totalPaidClaims: 0, paidThisYear: 0, lossRatio: 0.0 },
          collateral: { collateralHeld: 0, collateralType: null, collateralExpiry: null },
          gia: { giaExecuted: false, giaDate: null, giaParties: null, giaVersion: null },
          openExposure: { totalExposure: Number(r.bondPenalty), netExposure: Number(r.bondPenalty), reinsuranceRecoverable: 0, exposureCategory: 'Pending' },
        },
        sourceLineage: Object.fromEntries(
          ['activeBonds','customerSince','fliqRate','dtf','pms','entryTypes','extendedSuspendedEntries',
           'addCvd','ldClaims','idBills','otherClaims','premium','paidClaims','collateral','gia','openExposure']
          .map(g => [g, { sourceFile: filename, sourceSheet: 'Sheet1', sourceRow: r.row, importBatchId: batchId, importTimestamp: now }])
        ),
      };
      records.push(newRecord);
      imported++;
    } else {
      skipped++;
    }
  });

  lsSet('uw_renewal_records', records);

  // Persist errors
  const newErrors = errors.map((e, i) => ({ id: `ERR-${batchId}-${i}`, batchId, ...e }));
  lsSet('uw_import_errors', [...importErrors, ...newErrors]);

  // Persist batch record
  const batch = {
    id: batchId,
    filename,
    sourceType,
    uploadedBy: 'admin@suretyiq.com',
    uploadedAt: now,
    importedAt: now,
    status: errors.length > 0 ? 'Completed with Errors' : 'Completed',
    totalRows: summary.totalRows || rows.length,
    validRows: imported,
    errorRows: summary.errorRows || 0,
    duplicateRows: summary.duplicateRows || 0,
    sheets: ['Sheet1'],
    notes: `Imported via UI. ${imported} records added, ${skipped} skipped.`,
  };
  lsSet('uw_import_batches', [batch, ...batches]);

  // Audit log
  const auditEntry = {
    id: `AUD-IMP-${Date.now()}`,
    action: `Data Import Confirmed: ${filename}`,
    actor: 'admin@suretyiq.com',
    detail: `Batch ${batchId}: ${imported} imported, ${skipped} skipped, ${errors.length} errors.`,
    timestamp: now,
  };
  const log = lsGet('uw_audit_log', []);
  lsSet('uw_audit_log', [auditEntry, ...log]);

  return { imported, skipped, errors: newErrors, batchId };
}

/**
 * getImportHistory — Returns all import batches sorted by date descending.
 */
export async function getImportHistory() {
  ensureImportSeeded();
  await delay();
  const batches = lsGet('uw_import_batches', SEED_IMPORT_BATCHES);
  return [...batches].sort((a, b) => new Date(b.uploadedAt) - new Date(a.uploadedAt));
}

/**
 * getImportBatchById — Returns a single batch with its associated errors.
 */
export async function getImportBatchById(batchId) {
  ensureImportSeeded();
  await delay();
  const batches = lsGet('uw_import_batches', SEED_IMPORT_BATCHES);
  const errors = lsGet('uw_import_errors', SEED_IMPORT_ERRORS);
  const batch = batches.find(b => b.id === batchId) || null;
  if (!batch) return null;
  return { ...batch, errors: errors.filter(e => e.batchId === batchId) };
}

/**
 * getRenewalRecords — Returns normalized renewal records with optional filters.
 * filters: { search, caseId, principalId, bondType }
 */
export async function getRenewalRecords(filters = {}) {
  ensureImportSeeded();
  await delay();
  let records = lsGet('uw_renewal_records', SEED_RENEWAL_RECORDS);
  if (filters.caseId) records = records.filter(r => r.caseId === filters.caseId);
  if (filters.principalId) records = records.filter(r => r.principalId === filters.principalId);
  if (filters.bondType) records = records.filter(r => r.bondType === filters.bondType);
  if (filters.search) {
    const q = filters.search.toLowerCase();
    records = records.filter(r =>
      (r.principalName || '').toLowerCase().includes(q) ||
      (r.principalId || '').toLowerCase().includes(q) ||
      (r.bondType || '').toLowerCase().includes(q) ||
      (r.canonicalKey || '').toLowerCase().includes(q)
    );
  }
  return records;
}

/**
 * getRenewalRecordById — Returns a single normalized renewal record by id.
 */
export async function getRenewalRecordById(id) {
  ensureImportSeeded();
  await delay();
  const records = lsGet('uw_renewal_records', SEED_RENEWAL_RECORDS);
  return records.find(r => r.id === id) || null;
}

/**
 * getRenewalSourceLineage — Returns the source lineage map for all data groups
 * of a given renewal record.
 */
export async function getRenewalSourceLineage(renewalId) {
  ensureImportSeeded();
  await delay();
  const records = lsGet('uw_renewal_records', SEED_RENEWAL_RECORDS);
  const record = records.find(r => r.id === renewalId);
  if (!record) return null;
  return record.sourceLineage || {};
}

/**
 * searchRenewals — Full-text search across principalName, principalId, bondType.
 */
export async function searchRenewals(query) {
  ensureImportSeeded();
  await delay();
  if (!query || !query.trim()) {
    return lsGet('uw_renewal_records', SEED_RENEWAL_RECORDS);
  }
  const q = query.toLowerCase();
  const records = lsGet('uw_renewal_records', SEED_RENEWAL_RECORDS);
  return records.filter(r =>
    (r.principalName || '').toLowerCase().includes(q) ||
    (r.principalId || '').toLowerCase().includes(q) ||
    (r.bondType || '').toLowerCase().includes(q)
  );
}

