349: export async function submitUWDecision(caseId, decision) {
350:   ensureSeeded();
351:   await delay(300);
352:   const cases = lsGet('uw_cases', SEED_CASES);
353:   // Support both { status } (from RenewalPipeline) and { type } (legacy) shapes
354:   const decisionKey = decision.status || decision.type || 'Decision Made';
355:   const statusMap = {
356:     'Bound': 'Bound',
357:     'Approve': 'Bound',
358:     'Decision Made': 'Decision Made',
359:     'Approve with Conditions': 'Decision Made',
360:     'Decline': 'Decision Made',
361:     'Pending IR': 'Pending IR',
362:     'Request More Info': 'Pending IR',
363:   };
364:   const newStatus = statusMap[decisionKey] || decisionKey;
365:   const updated = cases.map(c => c.id === caseId ? { ...c, status: newStatus, lastDecision: decision } : c);
366:   lsSet('uw_cases', updated);
367: 
368:   // Log to audit
369:   const auditLog = lsGet('uw_audit_log', []);
370:   auditLog.push({
371:     id: `AUD-${Date.now()}`,
372:     caseId,
373:     action: `UW Decision: ${decisionKey}`,
374:     actor: decision.uwName || 'Underwriter',
375:     detail: decision.notes || '',
376:     timestamp: new Date().toISOString(),
377:   });
378:   lsSet('uw_audit_log', auditLog);
379: 
380:   return updated.find(c => c.id === caseId) || null;
381: }
