export async function acknowledgeAIBrief(caseId, overrideData = null) {
  ensureSeeded();
  await delay();
  const advisories = lsGet('uw_ai_advisories', SEED_AI_ADVISORIES);
  if (advisories[caseId]) {
    advisories[caseId] = {
      ...advisories[caseId],
      uwAcknowledged: true,
      acknowledged: true,
