  const hasData = data && Object.values(data).some(v => v !== null && v !== undefined && v !== '');

  return (
    <div className={`border rounded-lg overflow-hidden ${hasData ? 'border-slate-200' : 'border-dashed border-slate-200 opacity-60'}`}>
