  add_cvd_activity: 'ADD/CVD Activity',
  entry_activity: 'Entry Activity',
  extended_entry: 'Extended Entry',
  suspended_entry: 'Suspended Entry',
  missing_data: 'Missing Data',
  data_quality: 'Data Quality Issue',
  gia_change: 'GIA Change',
