};

// Status configuration
const STATUS_CONFIG = {
  active: {
    label: 'Active',
    color: 'bg-amber-100 text-amber-700',
    icon: Bell
  },
  acknowledged: {
    label: 'Acknowledged',
    color: 'bg-blue-100 text-blue-700',
    icon: CheckSquare
  },
  resolved: {
    label: 'Resolved',
