716: export async function generateSignals(caseId) {
717:   ensureSeeded();
718:   await delay(300);
719:   
720:   const rules = await getSignalRules();
721:   const currentCase = await getCaseById(caseId);
722:   if (!currentCase) return { generated: 0, signals: [] };
723:   
724:   // Get previous snapshot for comparison
725:   const processedKey = _getProcessedSnapshotKey(caseId);
726:   const previousSnapshot = lsGet(processedKey, null);
727:   
728:   // Check if snapshot has actually changed (deduplication)
729:   if (!_hasSnapshotChanged(caseId, currentCase)) {
730:     return { generated: 0, signals: [], message: 'No changes detected - signals already up to date' };
731:   }
732:   
733:   // Detect new signals
734:   const newSignals = _detectSignals(currentCase, previousSnapshot, rules);
735:   
736:   if (newSignals.length > 0) {
737:     // Get existing signals
738:     const existingSignals = lsGet(SIGNALS_KEY, []);
739:     
740:     // Deduplicate: don't add signals for the same type that are already active
741:     const activeSignals = existingSignals.filter(s => s.caseId === caseId && s.status === SIGNAL_STATUS.ACTIVE);
742:     const activeTypes = new Set(activeSignals.map(s => s.type));
743:     
744:     const uniqueNewSignals = newSignals.filter(s => !activeTypes.has(s.type));
745:     
746:     if (uniqueNewSignals.length > 0) {
747:       // Add new signals
748:       const updatedSignals = [...existingSignals, ...uniqueNewSignals];
749:       lsSet(SIGNALS_KEY, updatedSignals);
750:       
751:       // Log to signal history
752:       const history = lsGet(SIGNAL_HISTORY_KEY, []);
753:       uniqueNewSignals.forEach(signal => {
754:         history.push({
755:           id: `HIST-${Date.now()}-${signal.id}`,
756:           signalId: signal.id,
757:           caseId: signal.caseId,
758:           action: 'GENERATED',
759:           timestamp: new Date().toISOString(),
760:           details: `Signal ${signal.type} generated with severity ${signal.severity}`,
761:         });
762:       });
763:       lsSet(SIGNAL_HISTORY_KEY, history);
764:     }
765:     
766:     // Save current snapshot as processed
767:     _saveProcessedSnapshot(caseId, currentCase);
768:     
769:     return { 
770:       generated: uniqueNewSignals.length, 
771:       signals: uniqueNewSignals,
772:       skipped: newSignals.length - uniqueNewSignals.length,
773:     };
774:   }
775:   
776:   // Save snapshot even if no signals generated
777:   _saveProcessedSnapshot(caseId, currentCase);
778:   return { generated: 0, signals: [], message: 'No material changes detected' };
779: }
