781:   let signals = lsGet(SIGNALS_KEY, []);
782:   
783:   if (filters.caseId) signals = signals.filter(s => s.caseId === filters.caseId);
784:   if (filters.severity) signals = signals.filter(s => s.severity === filters.severity);
785:   if (filters.type) signals = signals.filter(s => s.type === filters.type);
786:   if (filters.status) signals = signals.filter(s => s.status === filters.status);
787:   if (filters.activeOnly) signals = signals.filter(s => s.status === SIGNAL_STATUS.ACTIVE);
788:   if (filters.dateFrom) {
789:     const fromDate = new Date(filters.dateFrom);
790:     signals = signals.filter(s => new Date(s.detectionTimestamp) >= fromDate);
791:   }
792:   if (filters.dateTo) {
793:     const toDate = new Date(filters.dateTo);
794:     signals = signals.filter(s => new Date(s.detectionTimestamp) <= toDate);
795:   }
796:   
797:   // Sort by severity (highest first) then by detection timestamp (newest first)
798:   signals.sort((a, b) => {
799:     const severityDiff = SIGNAL_SEVERITY_ORDER.indexOf(b.severity) - SIGNAL_SEVERITY_ORDER.indexOf(a.severity);
800:     if (severityDiff !== 0) return severityDiff;
801:     return new Date(b.detectionTimestamp) - new Date(a.detectionTimestamp);
802:   });
803:   
804:   return signals;
805: }
