917:   
918:   const updatedSignals = signals.map(s => {
919:     if (s.id === signalId) {
920:       return {
921:         ...s,
922:         status: SIGNAL_STATUS.ACKNOWLEDGED,
923:         acknowledgedBy: userData.userName || userData.userId || 'System',
924:         acknowledgedAt: new Date().toISOString(),
925:         acknowledgmentNote: userData.note || null,
926:       };
927:     }
928:     return s;
929:   });
930:   
931:   lsSet(SIGNALS_KEY, updatedSignals);
932:   
933:   // Log to history
934:   const history = lsGet(SIGNAL_HISTORY_KEY, []);
935:   history.push({
936:     id: `HIST-${Date.now()}`,
937:     signalId,
938:     caseId: signal.caseId,
939:     action: 'ACKNOWLEDGED',
940:     timestamp: new Date().toISOString(),
941:     actor: userData.userName || userData.userId || 'System',
942:     details: userData.note || 'Signal acknowledged',
943:   });
944:   lsSet(SIGNAL_HISTORY_KEY, history);
945:   
946:   return updatedSignals.find(s => s.id === signalId);
947: }
