991:   let history = lsGet(SIGNAL_HISTORY_KEY, []);
992:   
993:   if (filters.caseId) history = history.filter(h => h.caseId === filters.caseId);
994:   if (filters.signalId) history = history.filter(h => h.signalId === filters.signalId);
995:   if (filters.action) history = history.filter(h => h.action === filters.action);
