825: export async function generateSignals(caseId) {
826:   ensureSeeded();
827:   await delay(300);
828:   
829:   const rules = await getSignalRules();
830:   const currentCase = await getCaseById(caseId);
831:   if (!currentCase) return { generated: 0, signals: [] };
832:   
833:   // Get previous snapshot for comparison
834:   const processedKey = _getProcessedSnapshotKey(caseId);
835:   const previousSnapshot = lsGet(processedKey, null);
836:   
837:   // Check if snapshot has actually changed (deduplication)
838:   if (!_hasSnapshotChanged(caseId, currentCase)) {
839:     return { generated: 0, signals: [], message: 'No changes detected - signals already up to date' };
840:   }
841:   
842:   // Detect new signals
843:   const newSignals = _detectSignals(currentCase, previousSnapshot, rules);
844:   
845:   if (newSignals.length > 0) {
846:     // Get existing signals
847:     const existingSignals = lsGet(SIGNALS_KEY, []);
848:     
849:     // Deduplicate: don't add signals for the same type that are already active
850:     const activeSignals = existingSignals.filter(s => s.caseId === caseId && s.status === SIGNAL_STATUS.ACTIVE);
851:     const activeTypes = new Set(activeSignals.map(s => s.type));
852:     
853:     const uniqueNewSignals = newSignals.filter(s => !activeTypes.has(s.type));
854:     
855:     if (uniqueNewSignals.length > 0) {
856:       // Add new signals
857:       const updatedSignals = [...existingSignals, ...uniqueNewSignals];
858:       lsSet(SIGNALS_KEY, updatedSignals);
859:       
860:       // Log to signal history
861:       const history = lsGet(SIGNAL_HISTORY_KEY, []);
862:       uniqueNewSignals.forEach(signal => {
863:         history.push({
864:           id: `HIST-${Date.now()}-${signal.id}`,
865:           signalId: signal.id,
866:           caseId: signal.caseId,
867:           action: 'GENERATED',
868:           timestamp: new Date().toISOString(),
869:           details: `Signal ${signal.type} generated with severity ${signal.severity}`,
870:         });
871:       });
872:       lsSet(SIGNAL_HISTORY_KEY, history);
873:     }
874:     
875:     // Save current snapshot as processed
876:     _saveProcessedSnapshot(caseId, currentCase);
877:     
878:     return { 
879:       generated: uniqueNewSignals.length, 
880:       signals: uniqueNewSignals,
881:       skipped: newSignals.length - uniqueNewSignals.length,
882:     };
883:   }
884:   
885:   // Save snapshot even if no signals generated
886:   _saveProcessedSnapshot(caseId, currentCase);
887:   return { generated: 0, signals: [], message: 'No material changes detected' };
888: }
