  ensureSeeded();
  await delay();
  const corr = lsGet('uw_correspondence', SEED_CORRESPONDENCE);
  const newCorr = {
    id: `CO-${Date.now()}`,
    sentAt: new Date().toISOString(),
    timestamp: new Date().toISOString(),
    status: 'Sent',
    ...data,
  };
  corr.push(newCorr);
  lsSet('uw_correspondence', corr);
  return newCorr;
}

