export async function getRenewalIntelligence(caseId) {
  ensureSeeded();
  await delay();
  const cases = lsGet('uw_cases', SEED_CASES);
  const c = cases.find(x => x.id === caseId);
  if (!c) return null;
  return {
    caseId,
    riskScore: c.riskScore || 0,
    financialStrength: c.financialStrength || 'N/A',
