      dtf: { averageDtf: c.riskScore ? (c.riskScore * 0.8).toFixed(1) : '', minDtf: '', maxDtf: '', period: '2026' },
      pms: { score: c.creditScore || '', grade: c.financialStrength || '', assessmentDate: c.effectiveDate || '', notes: '' },
