              >
                <option value="all">All</option>
                {recommendations.map(r => <option key={r} value={r}>{r}</option>)}
              </select>
            </div>
            {/* Cards */}
            <div className="p-3 space-y-3 max-h-[600px] overflow-y-auto">
              {filteredCases.length === 0 ? (
