                  <p className="text-sm text-slate-400">No briefs match your filters.</p>
                </div>
              ) : (
                filteredCases.map(c => (
                  <BriefCard
                    key={c.id}
                    caseItem={c}
                    advisory={advisoryMap[c.id]}
                    renewalRecord={recordMap[c.id]}
                    selected={selectedCaseId === c.id}
                    onClick={() => setSelectedCaseId(c.id)}
                  />
                ))
              )}
            </div>
          </div>
        </div>

